    static void render(float[][] faces, PoseStack pose, VertexConsumer out, int light) {
        PoseStack.Pose transform = pose.last();
        for (float[] q : faces) for (int corner = 0; corner < 4; corner++) {
            int i = 3 + corner * 5;
            out.addVertex(transform, q[i], q[i + 1], q[i + 2]).setColor(255, 255, 255, 255)
                .setUv(q[i + 3], q[i + 4]).setOverlay(OverlayTexture.NO_OVERLAY)
                .setLight(light).setNormal(transform, q[0], q[1], q[2]);
        }
    }
